#ifndef G2O_CONFIG_H
#define G2O_CONFIG_H

// Normally generated by CMake's configure_file() from config.h.in based on
// which optional G2O_* features were detected/enabled (CHOLMOD, CSparse,
// OpenGL, OpenMP, shared libs, spdlog logging, ...). This overlay vendors
// only the Eigen-only core of g2o (see BUILD.bazel's top-of-file comment
// for why), so every one of those toggles is off -- which collapses
// config.h.in's #cmakedefine block down to just the one macro it always
// defines regardless.
#define G2O_DELETE_IMPLICITLY_OWNED_OBJECTS 1

#endif  // G2O_CONFIG_H
